input.command:
cat > /tmp/fix.cjs <<'EOF'
const fs=require('fs');
const out=require('child_process').spawnSync('node',['.claude/skills/angular-facts/ng-facts.mjs','check','--root','.','--all'],{encoding:'utf8'}).stdout+'';
const locs=[...out.matchAll(/^\s+(src\/\S+?\.ts):(\d+):(\d+)$/gm)].map(m=>[m[1],+m[2],+m[3]]);
locs.sort((a,b)=>b[2]-a[2]);
for(const [f,l,c] of locs){const L=fs.readFileSync(f,'utf8').split('\n');const s=L[l-1];
 if(s.substr(c-1,14)!=='disableTooltip'){console.log('MISMATCH',f,l,c);continue}
 L[l-1]=s.slice(0,c-1)+'hideHint'+s.slice(c-1+14);fs.writeFileSync(f,L.join('\n'));}
console.log(locs.length);
EOF
node /tmp/fix.cjs
sed -i 's/pill.setInput("disableTooltip"/pill.setInput("hideHint"/' src/app/lib/pill-tray.component.ts
sed -i '21s/\[disableTooltip\]/[hideHint]/g;22s/\[disableTooltip\]/[hideHint]/g' src/styles.css
git diff -U0 src/app/lib/pill-tray.component.ts src/styles.css | grep '^[+-]'
npx ngc -p tsconfig.json; node .claude/skills/angular-facts/leftovers.mjs PillComponent.disableTooltip --final --root . | head -5

